class MAction:
    """Bind Action to Sub-Expression
    <maction actiontype> expressoins </maction>
    """
    name = "maction"
    num_args_map = {
        'statusline': 2,
        'tooltip': 2,
        'input': 1,
    }

    def __init__(self, attrs):
        self.children = []
        self.attrs = attrs
        if attrs.get('actiontype') is None:
            raise RuntimeError(self.name + ' must have actiontype')

    def __str__(self):
        return str(self._selected_exp())

    def append(self, child):
        num_args = self.num_args_map.get(self.attrs['actiontype'])
        if num_args is not None and len(self.children) == num_args:
            raise RuntimeError('Too large number of children for ' + self.name)
        self.children.append(child)

    def is_space_like(self):
        return self._selected_exp().is_space_like()

    def embellished_op(self):
        return self._selected_exp().embellished_op()

    def _selected_exp(self):
        if self.attrs['actiontype'] == 'toggle':
            idx = int(self.attrs.get('selection', '1')) - 1
        else:
            idx = 0
        return self.children[idx]

class MathMLHandler(xml.sax.handler.ContentHandler):
    CONVERSION_MAP = dict((cls.name, cls) for cls in (
        MI, MN, MO, MText, MSpace, MS,
        Math, MRow,
        MSqrt, MRoot,
        MFrac,
        MStyle, MPadded, MPhantom,
        MFenced, MEnclose,
        MSub, MSup, MSubSup,
        MUnder, MOver, MUnderOver,
        MMultiScripts, MPreScripts, MNone,
        MTable, MTableRow, MTableData,
        MAction,
        ))
    IGNORED_ELEMENTS = ('annotation-xml', 'annotation')
    SKIPPED_ELEMENTS = ('semantics',)

    def __init__(self):
        super(MathMLHandler, self).__init__()
        self._stack = []
        self._stack.append([])
        self._in_ignore_elems = 0

    def startElement(self, name, attrs):
        if name in MathMLHandler.IGNORED_ELEMENTS:
            self._in_ignore_elems += 1
            return
        if self._in_ignore_elems > 0 or name in MathMLHandler.SKIPPED_ELEMENTS:
            return
        if name not in MathMLHandler.CONVERSION_MAP:
            raise NotImplementedError(name + ' is not Implemented')
        self._stack.append(MathMLHandler.CONVERSION_MAP[name](attrs))

    def endElement(self, name):
        if name in MathMLHandler.IGNORED_ELEMENTS:
            self._in_ignore_elems -= 1
            return
        if self._in_ignore_elems > 0 or name in MathMLHandler.SKIPPED_ELEMENTS:
            return
        elem = self._stack.pop()
        if isinstance(elem, (MRow, InferredMRowElement)):
            elem.merge_children()
        self._stack[-1].append(elem)

    def characters(self, content):
        if hasattr(self._stack[-1], 'set_text'):
            self._stack[-1].set_text(content)
        else:
            if content.strip() != '':
                print(content)

    def result(self):
        return str(self._stack[-1][0])

def convert(mathml_xml, additional_entities=None):
    """Convert MathML text to OMML text
    """
    handler = MathMLHandler()
    entities = {
        'pi': 0x03c0,
        'ExponentialE': 0x2147,
        'ee': 0x2147,
        'ImaginaryI': 0x2148,
        'ii': 0x2148,
        'gamma': 0x03b3,
        'infin': 0x221e,
        'infty': 0x221e,
    }
    if additional_entities is not None:
        entities.update(additional_entities)
    input_xml = (
        r"""<!DOCTYPE math [ """ +
        ''.join('<!ENTITY %s "&#x%04X;">' % item for item in entities.items()) +
        r""" ]>""" +
        mathml_xml)
    xml.sax.parseString(input_xml, handler)
    return handler.result()

common/calculation_context.py:
"""Capture the existing generator's calculation at compose(), without saving a report."""
import contextlib, io, importlib.util, json, math, os, sys, tempfile
from pathlib import Path

class Captured(BaseException):
    def __init__(self, data): self.data=data

class NullDocument:
    def __init__(self,*args,**kwargs): pass
    def __getattr__(self,name): return lambda *args,**kwargs: None

def calculate(experiment):
    experiment=Path(experiment).resolve()
    sys.path.insert(0,str(experiment.parent))
    from common.data_io import load_data
    data=load_data(str(experiment/'data.json'))
    spec=importlib.util.spec_from_file_location('_context_generator',experiment/'generate.py')
    module=importlib.util.module_from_spec(spec)
    with contextlib.redirect_stdout(io.StringIO()):
        spec.loader.exec_module(module)
        module.DocxReportWriter=NullDocument
        def capture(_, values): raise Captured(values)
        module.compose=capture
        # Plots preceding compose are irrelevant to the numerical context.
        for name in list(vars(module)):
            if name.startswith('_plot') and callable(getattr(module,name)):
                setattr(module,name,lambda *args,**kwargs:None)
        with tempfile.TemporaryDirectory(prefix='lab-context-') as tmp:
            try: module._generate_docx(data,str(Path(tmp)/'unused.docx'))
            except Captured as result:
                values=dict(data); values.update(result.data)
                # Nested diagnostic objects need not be serialized to the AI.
                scalars={k:v for k,v in values.items() if isinstance(v,(str,int,float)) and not isinstance(v,bool)}
                if any(isinstance(v,float) and not math.isfinite(v) for v in scalars.values()):
                    raise ValueError('计算结果含非有限数值，请检查实验数据')
                return {'_kind':'generic','_inputs':data,**scalars}
    raise ValueError('未得到有效计算结果，请检查输入')

if __name__=='__main__':
    try: print(json.dumps(calculate(sys.argv[1]),ensure_ascii=False,allow_nan=False))
    except Exception as error:
        print(str(error),file=sys.stderr);sys.exit(1)

common/content_policy.py:
"""Reject unbound experimental values in AI-imported prose."""
import re


def contains_writing_instructions(text):
    return any(fragment in re.sub(r'\s+', '', str(text)) for fragment in (
        '误差应结合本次数据和仪器说明评定', '按知识库口径',
        '用户填写', '用户提供的', '不能采用示例', '未照抄源文档',
        '不虚构数值上限', '保留所有占位符', '只输出改写后的',
    ))

def inspect_text(text, data=None):
    import math
    text = str(text)
    def replace(m):
        key, fmt = m.groups()
        if not re.fullmatch(r'%(?:\.(?:[0-9]|1[0-2]))?[fgesd]', fmt):
            raise ValueError('实验数值占位符格式无效：' + key)
        if data is not None:
            value = data.get(key)
            finite = isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)
            if key.startswith('_') or key not in data or not (finite or (fmt.endswith('s') and isinstance(value, str))):
                raise ValueError('模板引用未知或无效实验量：' + key)
        return ''
    rest = re.sub(r'%%DATA:([^:]+):(.+?)%%', replace, text)
    if '%%DATA:' in rest:raise ValueError('实验数值占位符格式不完整')
    rest = re.sub(r'\\(?:mathrm|text)\{([^{}]*)\}', r'\1', rest)
    rest = re.sub(r'\\[ ,]', ' ', rest)
    num = r'(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)'
    rules = [
        ('r_mohm', r'(?:\bR\b\s*=|测得(?:的)?(?:高电阻|电阻)(?:为|是|值为)?\s*[=:：]?)\s*'+num+r'\s*(MΩ|兆欧|kΩ|Ω)', {'MΩ':1,'兆欧':1,'kΩ':.001,'Ω':.000001}),
        ('r_0', r'(?:\bR_\{?0\}?\s*=|(?:电阻)?标称值(?:为|是)?\s*[=:：]?)\s*'+num+r'\s*(MΩ|兆欧|kΩ|Ω)?', {'MΩ':1,'兆欧':1,'kΩ':.001,'Ω':.000001}),
        ('c_x_bar', r'(?:\bC_\{?x\}?\s*=|测得(?:的)?电容(?:为|是|值为)?\s*[=:：]?)\s*'+num+r'\s*(μF|微法|nF|F)', {'μF':1,'微法':1,'nF':.001,'F':1000000}),
    ]
    for key,value in (data or {}).items():
        if re.fullmatch(r'[A-Za-z][A-Za-z0-9_]*',key) and len(key)>2 and key!='r_0' and isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value):
            rules.append((key,r'\b'+key+r'\s*=\s*'+num,{}))
    for key, pattern, units in rules:
        expected = (data or {}).get(key)
        if isinstance(expected, bool) or not isinstance(expected,(int,float)) or not math.isfinite(expected):continue
        for m in re.finditer(pattern, rest):
            clause=re.split(r'[。；;\n]',rest[:m.start()])[-1]
            if re.search(r'例如|示例|假设|假定|参考',clause):continue
            token=m.group(1);unit=m.group(2) if len(m.groups())>1 else None;factor=units.get(unit,1)
            parts=token.lower().split('e');decimals=len(parts[0].split('.')[1]) if '.' in parts[0] else 0
            tolerance=.5*10**(int(parts[1]) if len(parts)>1 else 0)*10**(-decimals)*factor+1e-10*max(1,abs(expected))
            if abs(float(token)*factor-expected)>tolerance:
                raise ValueError('文本中的 '+key+' 与当前计算结果不一致，请核对或使用数据占位符。')
    prose=re.sub(r'\$\$[\s\S]*?\$\$|\$[^$]*\$|\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]', '', rest)
    prose=re.sub(r'(?m)^\s*(?:[（(]?\d+[）).、．])\s*','',prose).replace('273.15','')
    warnings=[]
    if re.search(r'-?\d+(?:\.\d+)?\s*(?:MΩ|兆欧|kΩ|μF|微法|nF|μC|微库|mV|μV|mm|nm|cm|m/s|kHz|mA|Ω|欧姆|℃|秒|s\b|伏|V\b|A\b|%|％)|(?:测得|结果为|标称值|精度|分辨力|误差限)[^，。；\n]{0,16}\d',prose):
        warnings.append({'code':'UNVERIFIED_QUANTITY','message':'文本含未绑定数据占位符的数值，请核对其来源、单位和精度；此提醒不阻止生成。'})
    return {'text':text,'warnings':warnings}


def validate_polish(text, data=None):
    if contains_writing_instructions(text):
        raise ValueError('报告正文包含通用写作指导，请改写为本实验的误差来源分析')
    result=inspect_text(text,data)
    if result['warnings']:
        import sys
        print('AI数值提醒 | UNVERIFIED_QUANTITY | 请核对未绑定数值的来源、单位和精度；不阻止生成。',file=sys.stderr,flush=True)
    return text

