# -*- coding: utf-8 -*-
"""变体组合模块。

同一个实验的报告/论文可以由不同"变体"章节组合而成：
- 实验目录下放置 variants.json：{章节名: [变体1文本, 变体2文本, 变体3文本, ...]}
- 应用通过环境变量 LAB_VARIANTS 传入本次组合选择：{"章节名": 变体序号, ...}
- 文本支持 $...$ 内联公式（由 DocxReportWriter.add_paragraph_rich 渲染）
- 文本支持数据占位符 %%DATA:<key>:<format>%%，组合时从计算结果注入
  （format 为 printf 风格，如 %%DATA:Y:%.2f%%）

无 variants.json 或未提供选择时，compose() 返回空 dict，报告保持原有行为。
"""

import json
import os
import re
import sys

DATA_PATTERN = re.compile(r"%%DATA:([^:]+):(.+?)%%")


def load_variants(script_dir: str):
    """读取实验目录下的 variants.json；不存在时返回 None。"""
    p = os.path.join(script_dir, "variants.json")
    if not os.path.exists(p):
        return None
    with open(p, encoding="utf-8") as f:
        return json.load(f)


def _job_value(name, legacy):
    job = os.environ.get("LAB_JOB_INPUT")
    if job:
        p = os.path.realpath(job)
        if os.path.dirname(p) != os.path.realpath(os.getcwd()) or os.path.getsize(p) > 512 * 1024:
            raise ValueError("任务输入文件无效")
        with open(p, encoding="utf-8") as f:
            return json.dumps(json.load(f).get(name, {}), ensure_ascii=False)
    return os.environ.get(legacy, "").strip()


def get_variant_choices():
    """读取环境变量 LAB_VARIANTS 中的组合选择（JSON dict）。未提供返回 None。"""
    raw = _job_value("variants", "LAB_VARIANTS")
    if not raw:
        return None
    try:
        d = json.loads(raw)
        return d if isinstance(d, dict) else None
    except Exception:
        return None


def get_disabled_sections():
    """读取 LAB_JOB_INPUT.disabledSections（或旧环境变量 LAB_DISABLED_SECTIONS）中被禁用的
    变体章节名列表（如 ["实验原理"]）。未提供返回空集合，即全部章节启用。"""
    raw = _job_value("disabledSections", "LAB_DISABLED_SECTIONS")
    if not raw:
        return set()
    try:
        d = json.loads(raw)
        return {str(s) for s in d} if isinstance(d, list) else set()
    except Exception:
        return set()


def render_variant(text: str, data: dict) -> str:
    """将 %%DATA:<key>:<format>%% 占位符替换为计算结果中的数值。"""

    def repl(m):
        key, fmt = m.group(1), m.group(2)
        val = data.get(key)
        if val is None:
            raise ValueError("计算结果缺少占位符字段：" + key)
        try:
            return fmt % val
        except Exception as error:
            raise ValueError("计算结果占位符格式无效：" + key) from error

    return DATA_PATTERN.sub(repl, text)


def get_polish_overrides():
    """读取环境变量 LAB_POLISH 中的润色导入（JSON {章节名: Markdown 文本}）。"""
    raw = _job_value("polish", "LAB_POLISH")
    if not raw:
        return None
    try:
        d = json.loads(raw)
        return d if isinstance(d, dict) else None
    except Exception:
        return None


_HEADING_RE = re.compile(r"(?m)^[ \t]*#{1,6}[ \t]*[^\n]*\n?")
_BULLET_RE = re.compile(r"(?m)^[ \t]*[-*+][ \t]+")
_HR_RE = re.compile(r"(?m)^[ \t]*[-=*_]{3,}[ \t]*$")
_TABLE_SEP_CELL = re.compile(r":?-+:?")

SECTIONS_MARKER = ".LAB_SECTIONS_JSON:"

# AI 常见输出：$$ 定界符与公式体分行 → 合并为单行 $$公式$$
_BLOCK_MATH_RE = re.compile(r"\$\$\s*([\s\S]*?)\s*\$\$")
# 裸数学片段判定：含 \命令 或 ^/_ 上下标
_MATH_TOKEN_RE = re.compile(r"\\[a-zA-Z]+|[_^]")
# 数学候选段：连续的西文/符号段（以汉字与中文标点为边界）
_NON_CJK_SEG_RE = re.compile(
    u"[^\u4e00-\u9fff\u3000-\u303f\uff00-\uffef\u2010-\u2027]+")
_TRAIL_PUNCT_RE = re.compile(r"^(.+?)([.,;:]+)$")


def _collapse_block_math(text):
    """把跨行的 $$...$$ 合并为单行，内部换行折叠为空格。"""

    def rep(m):
        inner = " ".join(m.group(1).split())
        return "$$" + inner + "$$" if inner else ""

    return _BLOCK_MATH_RE.sub(rep, text)


def _repair_bare_math(text):
    """$ 区域之外、含 \\命令 或 ^/_ 的裸数学片段自动包上 $...$。

    以汉字/中文标点为边界切出西文段，仅当段内含数学记号才包裹；
    已有的 $...$ 与 $$...$$ 区域原样保留，句尾标点移到 $ 外。
    """
    parts = re.split(r"(\$\$[^$]*\$\$|\$[^$]*\$)", text)
    out = []
    for i, part in enumerate(parts):
        if i % 2 == 1:
            out.append(part)
            continue

        def wrap(m):
            seg = m.group(0)
            if not _MATH_TOKEN_RE.search(seg):
                return seg
            stripped = seg.strip()
            if not stripped:
                return seg
            lead = seg[:len(seg) - len(seg.lstrip())]
            trail = seg[len(seg.rstrip()):]
            pm = _TRAIL_PUNCT_RE.match(stripped)
            if pm and len(pm.group(1)) > 1:
                stripped, punct = pm.group(1), pm.group(2)
            else:
                punct = ""
            return lead + "$" + stripped + "$" + punct + trail

        out.append(_NON_CJK_SEG_RE.sub(wrap, part))
    return "".join(out)


def normalize_polish_md(text):
    """把 AI 输出的 Markdown 预处理成报告富文本（保留 $...$ 与 $$...$$ 公式）。

    处理：markdown 表格降级为分号文本行、\\( \\) 与 \\[ \\] 归一为 $ 与 $$、
    逐行剥离标题井号/列表符/分割线/引用符、去粗斜体与行内代码标记。
    """
    lines = []
    for ln in text.splitlines():
        s = ln.strip()
        if s.startswith("|") or s.endswith("|"):
            cells = [c.strip() for c in s.strip("|").split("|")]
            if all(not c or _TABLE_SEP_CELL.fullmatch(c) for c in cells):
                continue  # 表头分隔行整行丢弃
            ln = "；".join(c for c in cells if c)
        lines.append(ln)
    text = "\n".join(lines)
    # 0. LaTeX 间距命令字面（\emsp \ensp \quad \qquad \hspace{...} \, \; \: \! \ ）
    #    统一替换为空格：Word UnicodeMath 不识别这些命令，防止进入公式/正文后
    #    以原文残留（后续公式预处理与保存兜底仍会再清一遍）
    text = re.sub(r"\\(?:emsp|ensp|qquad|quad|hspace\*?\{[^}]*\}|,|;|:|!| )", " ", text)
    text = text.replace(r"\[", "$$").replace(r"\]", "$$")
    text = text.replace(r"\(", "$").replace(r"\)", "$")
    text = _HEADING_RE.sub("", text)
    text = _BULLET_RE.sub("", text)
    text = _HR_RE.sub("", text)
    text = re.sub(r"(?m)^[ \t]*>[ \t]?", "", text)
    text = re.sub(r"\*\*(.+?)\*\*", r"\1", text)
    text = re.sub(r"__(.+?)__", r"\1", text)
    text = re.sub(r"(?<![\w$\\])\*([^*\n]+)\*(?![\w$])", r"\1", text)
    text = re.sub(r"`([^`\n]+)`", r"\1", text)
    # 4.5 跨行 $$...$$ 合并为单行（AI 常见的定界符独立成行写法）
    text = _collapse_block_math(text)
    # 4.6 裸数学修复：$ 区域之外含 \命令 或 ^/_ 的片段包上 $...$
    text = _repair_bare_math(text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


# 思考题整段润色文本 → 按问回答：切分规则与应用侧 importQuizAnswers 逐字一致
# （src/renderer.js 用 /\n(?=\d+\.\s)/，这里同一条正则，别只改一边）
_QUIZ_SPLIT_RE = re.compile(r"\n(?=\d+\.\s)")
_QUIZ_ITEM_RE = re.compile(r"^(\d+)\.\s*")
# 应用从 docx 截取思考题原文时是从关键字处开始的，整段文本首行常是章节标题
_QUIZ_HEAD_RE = re.compile(r"^[ \t]*(?:[一二三四五六七八九十]+、)?[ \t]*(?:课后)?(?:思考题|问题讨论)[ \t]*\n")


def split_quiz_polish(text: str) -> dict:
    """把「整段润色」的思考题文本拆成 {题号: [回答]}；识别不到题号时返回 {}。

    文本形如（首行章节标题可有可无，题目逐字保留是润色的硬约束）：
        思考题
        1. 题目……
        答：回答……
        2. 题目……
    """
    body = _QUIZ_HEAD_RE.sub("", text.strip(), count=1)
    out = {}
    for part in _QUIZ_SPLIT_RE.split(body):
        part = part.strip()
        m = _QUIZ_ITEM_RE.match(part)
        if not m:
            continue
        lines = part.split("\n", 1)
        answer = lines[1].strip() if len(lines) > 1 else ""
        if answer:
            out.setdefault(m.group(1), []).append(answer)
    return out


def get_custom_quiz():
    """读取应用传入的自定义思考题：{"questions": [...], "answers": {题号: [答案...]}}；无则 None。"""
    raw = _job_value("customQuiz", "LAB_CUSTOM_QUIZ")
    if not raw:
        return None
    try:
        d = json.loads(raw)
    except Exception:
        return None
    if not isinstance(d, dict):
        return None
    questions = [str(q).strip() for q in (d.get("questions") or []) if str(q or "").strip()]
    if not questions:
        return None
    answers = d.get("answers") if isinstance(d.get("answers"), dict) else {}
    return {"questions": questions, "answers": answers}


def render_custom_quiz(doc, data):
    """渲染用户自定义的思考题（题目 + 应用侧 AI 生成的答案）；返回 True 表示已渲染。

    返回 False 时调用方照常输出内置题目。答案按题号取，逐条过
    normalize_polish_md / render_variant（%%DATA%% 占位符与公式同样生效）。
    """
    quiz = get_custom_quiz()
    if not quiz:
        return False
    for i, q in enumerate(quiz["questions"], 1):
        doc.add_heading("%d. %s" % (i, q), level=2)
        answers = quiz["answers"].get(str(i))
        if answers is None:
            answers = quiz["answers"].get(i)
        if isinstance(answers, str):
            answers = [answers]
        from .content_policy import validate_polish
        rendered = [render_variant(normalize_polish_md(validate_polish(str(a), data)), data)
                    for a in (answers or []) if str(a or "").strip()]
        if rendered:
            doc.add_paragraph_rich(rendered[0])
        else:
            doc.add_paragraph("答：（本次未生成回答）")
    return True


def compose(script_dir: str, data: dict) -> dict:
    """按 LAB_VARIANTS 组合各章节文本，并应用 LAB_POLISH 润色导入覆盖。

    返回 {章节名: 渲染后文本}。LAB_POLISH 中提供的章节以润色文本覆盖变体
    （Markdown 先归一为报告富文本，%%DATA:%% 占位符对两者同样生效）。
    同时向 stdout 打印一行 SECTIONS_MARKER + JSON，由应用侧捕获并持久化为
    章节缓存（.lab_sections.json），供"按章节润色/导入重生成"读取原文。
    """
    variants = load_variants(script_dir) or {}
    choices = get_variant_choices()
    disabled = get_disabled_sections()
    enforce_policy = os.path.isfile(os.path.join(script_dir, "rag", "knowledge.json"))
    from .content_policy import validate_polish
    out = {}
    for section, texts in variants.items():
        if section in disabled:
            continue   # 该实验此章节被禁用（应用"变体管理"），报告中不再出现
        if section == "思考题":
            # 思考题：按问回答变体字典原样透传（题目在 generate.py 写死，
            # 生成器对每问随机选回答；LAB_POLISH 覆盖时下方循环替换为整段文本）
            if isinstance(texts, dict):
                out[section] = {qno: [render_variant(validate_polish(str(answer), data) if enforce_policy else str(answer), data)
                                     for answer in (answers if isinstance(answers, list) else [answers])]
                                for qno, answers in texts.items()}
            continue
        idx = 0 if enforce_policy else -1
        if choices and section in choices:
            try:
                idx = int(choices[section])
            except Exception:
                idx = -1
        if 0 <= idx < len(texts):
            if enforce_policy:
                validate_polish(texts[idx], data)
            out[section] = render_variant(texts[idx], data)
    for section, md in (get_polish_overrides() or {}).items():
        if section in disabled:
            continue   # 润色覆盖同样受章节开关约束
        if not isinstance(md, str) or not md.strip():
            continue
        from .content_policy import contains_writing_instructions
        if contains_writing_instructions(md):
            print('polish | 已跳过包含写作指导或软件说明的旧润色，使用当前实验正文；请重新润色。', file=sys.stderr, flush=True)
            continue
        from .content_policy import validate_polish
        if section == "思考题":
            # 整段润色文本自带题目与答案，而 generate.py 的题目写死、按问取回答：
            # 这里解析成按问回答，避免「整段文本」与「写死题目 + 兜底答案」各输出一遍。
            # 解析不到题号就忽略该覆盖（绝不整段输出）——报告退回写死题目 + 变体/兜底答案。
            quiz = split_quiz_polish(md)
            if not quiz:
                print("quiz-polish | 整段润色文本里没有识别到题号，已忽略该覆盖（避免与写死题目重复）",
                      file=sys.stderr, flush=True)
                continue
            base = out.get("思考题")
            merged = dict(base) if isinstance(base, dict) else {}
            for qno, answers in quiz.items():
                merged[qno] = [render_variant(normalize_polish_md(validate_polish(a, data)), data) for a in answers]
            out["思考题"] = merged
            continue
        out[section] = render_variant(normalize_polish_md(validate_polish(md, data)), data)
    from .report_style import error_points
    if isinstance(out.get('误差分析'), str):
        out['误差分析'] = error_points(out['误差分析'])
    if out:
        print(SECTIONS_MARKER + json.dumps(out, ensure_ascii=False), flush=True)
    return out


def variants_summary(script_dir: str) -> dict:
    """返回 {章节名: 变体数}，供应用展示变体库是否存在及规模。"""
    v = load_variants(script_dir)
    if not v:
        return {}
    return {section: len(texts) for section, texts in v.items()}

